CREATE TABLE wallets(workspace_id VARCHAR(36) PRIMARY KEY, monthly_remaining INT NOT NULL DEFAULT 0, extra_remaining INT NOT NULL DEFAULT 0, agent_seats INT NOT NULL DEFAULT 2, period_start TIMESTAMP, period_end TIMESTAMP, active BOOLEAN NOT NULL DEFAULT FALSE, CHECK(monthly_remaining>=0),CHECK(extra_remaining>=0),CHECK(agent_seats>=2));
CREATE TABLE purchases(id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL, request_key VARCHAR(100) NOT NULL, product VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(workspace_id,request_key),FOREIGN KEY(workspace_id) REFERENCES wallets(workspace_id));
CREATE TABLE reservations(id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL, user_id VARCHAR(36) NOT NULL, author_name VARCHAR(200) NOT NULL, company_name VARCHAR(200), simulator VARCHAR(30) NOT NULL, request_key VARCHAR(100) NOT NULL, request_hash VARCHAR(64) NOT NULL, state VARCHAR(20) NOT NULL, bucket VARCHAR(10) NOT NULL, result_id BIGINT, response_json LONGTEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(workspace_id,simulator,request_key),FOREIGN KEY(workspace_id) REFERENCES wallets(workspace_id));
CREATE TABLE credit_ledger(id VARCHAR(36) PRIMARY KEY,workspace_id VARCHAR(36) NOT NULL,actor_id VARCHAR(36),delta INT NOT NULL,reason VARCHAR(200) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES wallets(workspace_id));
CREATE INDEX idx_history_workspace ON reservations(workspace_id,state,created_at);
